import {buildPlan,resources,commands} from './operational-engine.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),short=id=>String(id||'').slice(0,8),chip=(v,c='')=>`<span class="chip ${c}">${esc(v)}</span>`;
const ui={scope:null,dest:'LE-GB-02',table:'party',result:null,read:null,preview:null,lastRequest:null,email:'updated.aster@example.invalid',controlsOpen:false};
export function operationalStrip(op){if(!op)return '';return `<div class="op-strip"><div><span class="eyebrow">NEW / OPERATIONAL DATA</span><b>Global party. Policy-bound relationships.</b><span>${op.model.scopes.length} independent scopes · ${op.projections.reduce((n,p)=>n+p.rows.length,0)} approved row copies · ${op.queue.length} pending routes</span></div><a href="#services" class="primary">Open service lab ↗</a><a href="#business" class="link">Explore the model</a></div>`;}
function chosen(op){const m=op.model,s=m.scopes.find(s=>s.id===ui.scope)||m.scopes[0];ui.scope=s.id;return {m,s};}
function selectors(op,cat){const {m,s}=chosen(op);return `<div class="op-selectors"><label>Major business key<select id="op-scope">${m.scopes.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Recipient legal entity<select id="op-dest">${cat.entities.filter(e=>e.id!==m.owner_entity_id).map(e=>`<option ${e.id===ui.dest?'selected':''} value="${e.id}">${e.id} · ${e.city}</option>`).join('')}</select></label><div>${chip(s.scope_kind==='party'?'PARTY KEY':'RELATIONSHIP KEY')}<small>data v${s.data_version} · policy g${s.policy_generation} · decision r${s.decision_revision}</small></div></div>`;}
function title(heading,sub){return `<div class="titlebar"><div><div class="eyebrow">OPERATIONAL FEDERATION / EDITION 03</div><h1>${heading}</h1><p class="subtitle">${sub}</p></div><a class="link" href="/design/operational-model.html" target="_blank" rel="noopener">Technical design ↗</a></div>`;}
export function businessPage(op,cat){const {m,s}=chosen(op),t=ui.table,cfg=m.tables[t],bound=m.bindings.filter(b=>b.resource_type===t),rules=m.rules.filter(r=>r.resource_type===t);return title('Business data. Sovereignty alongside.','Keep the operational model coherent. Resolve its sharing rules through a parallel control layer.')+`<div class="op-dual"><section class="op-plane"><div class="eyebrow">01 / BUSINESS SCHEMA</div><h2>The party relationship graph</h2><div class="op-graph"><div class="op-node op-root"><b>PARTY</b><span>Aster Example · person</span><small>One identity, several relationships</small></div><div class="op-branches"><div class="op-node"><b>PERSONAL RELATIONSHIP</b><span>Account holder → deposit + card</span><small>LE-GB-02 · contact profile</small></div><div class="op-node"><b>BUSINESS RELATIONSHIP</b><span>Signatory + organisation → loan</span><small>LE-GB-03 · minimal profile</small></div></div><div class="op-graph-tags">Consent & preferences · contact info · contact history<br>Alternate IDs · classifications · product holdings</div></div><p>Business rows contain business attributes and foreign keys. They carry no destination lists or residency flags.</p></section><section class="op-plane control"><div class="eyebrow">02 / SOVEREIGNTY SCHEMA</div><h2>Bind identities, intersect policies</h2><div class="op-rule"><b>Table defaults</b><span>Party → global minimum<br>Relationship graph → policy<br>History & sensitive identifiers → owner</span></div><div class="op-rule"><b>Major-key scopes</b><span>Party key / relationship key<br>Separate recipients, purpose and versions</span></div><div class="op-rule"><b>Resource constraints</b><span>Holding classification · party exclusions<br>Shared records keep their own restrictions</span></div><div class="op-rule"><b>Transaction hook → outbox</b><span>Change business data and bindings atomically.<br>Export only the approved, connected graph.</span></div></section></div><div class="pagecall"><b>Global identity is a field contract.</b> Only <code>id, global_party_id, party_type</code> travel in the global party scope. Names, contacts, relationship links and holdings do not follow automatically. Aster’s party minimum reaches all three stores; Example Trading’s party key excludes the US.</div><section class="panel"><div class="panelhead"><div><h2>Table → sovereignty mapping</h2><p>Select a dataset to inspect its keys, default and field contract.</p></div>${chip(Object.keys(m.tables).length+' business tables')}</div><div class="tablewrap"><table><thead><tr><th>Business table / service</th><th>Major key</th><th>Table default</th><th>Source rows</th></tr></thead><tbody>${Object.entries(m.tables).map(([name,c])=>`<tr data-op-table="${name}" tabindex="0" role="button" aria-label="Inspect ${name}" class="${name===t?'selected':''}"><td><b>${esc(name)}</b><div class="entity-sub">${esc(c.service)}</div></td><td><code>${esc(c.major_key)}</code></td><td>${chip(m.table_rules[name].mode,m.table_rules[name].mode==='owner_only'?'wait':'')}</td><td>${m.rows[name].length}</td></tr>`).join('')}</tbody></table></div></section><div class="op-detail-grid"><section class="panel pad"><div class="eyebrow">BUSINESS DATASET</div><h2>${esc(t)}</h2><div class="op-fieldlist">${Object.keys(cfg.columns).map(f=>`<span class="${cfg.export_fields.includes(f)?'':'withheld'}">${esc(f)}${!cfg.export_fields.includes(f)?' · owner':''}</span>`).join('')}</div><p class="tiny">Parent references: ${cfg.parents.map(p=>`${p.field} → ${p.table}.id`).join(' · ')||'Root business identity'}</p><p class="tiny">Global scope contract: ${cfg.global_fields.join(', ')}. ${cfg.owner_only?'Owner-only rule blocks export despite the registered schema.':''}</p></section><section class="panel pad"><div class="eyebrow">PARALLEL CONTROL BINDINGS</div><h2>${bound.length} bindings · ${rules.length} resource rules</h2><pre class="op-json">${esc(JSON.stringify({table_rule:m.table_rules[t],example_resource_rule:rules[0],binding:bound[0]},null,2))}</pre></section></div>`+selectors(op,cat)+`<div class="op-next"><div><h2>Try a transaction, then follow the copies.</h2><p>Change a contact once, reconcile two relationship scopes. Withdraw consent from just one.</p></div><a href="#services" class="primary">Open business services →</a></div>`;}
export function servicesPage(op,cat,stores,live){const {m,s}=chosen(op),plan=ui.preview||buildPlan(m,s,ui.dest,cat),actual=op.projections.find(p=>p.scope_id===s.id&&p.destination_entity_id===ui.dest),rs=resources(m,s),entity=cat.entities.find(e=>e.id===ui.dest),st=stores.find(x=>x.id===entity.store_id),fresh=actual&&actual.decision_revision===s.decision_revision&&actual.policy_generation===s.policy_generation&&actual.placement_version===entity.placement_version;const tx=ui.result||op.transactions.at(-1);const consent=m.rows.consent.find(c=>c.relationship_id===s.relationship_id&&c.channel==='EMAIL');const globalScope=m.scopes.find(x=>x.scope_kind==='party'&&x.primary_party_id===s.primary_party_id);return title('Business services lab','Run a local business transaction. Watch independent party and relationship projections reconcile.')+selectors(op,cat)+`<div class="op-global"><div><span class="eyebrow">GLOBAL PARTY MINIMUM</span><h2>One party identity. Independent distribution.</h2><p>Aster’s identity may exist in the US without any US relationship copy. The legal owner remains in Singapore.</p></div><div class="op-hubs">${cat.stores.map(h=>{const ps=op.projections.filter(p=>p.scope_id===globalScope?.id&&p.store_id===h.id&&p.rows.length);const present=h.country==='SG'||ps.length;return `<div class="op-hub ${present?'present':''}"><span>${h.country}</span><b>${h.city}</b><small>${h.country==='SG'?'Authoritative party':present?ps.length+' entitled party copies':'No approved party copy'}</small></div>`;}).join('')}</div></div><div class="op-service-layout"><section class="panel"><div class="panelhead"><div><h2>Command workspace</h2><p>${s.scope_kind==='party'?'Party-wide resource constraints':'Local business API · relationship '+short(s.relationship_id)}</p></div>${chip(consent?.status||'IDENTITY ONLY',consent?.status==='WITHDRAWN'?'denied':'')}</div><div class="pad"><div class="op-steps"><span>Gateway</span><i>→</i><span>Regional service</span><i>→</i><span>Local ACID + outbox</span></div>${s.scope_kind==='relationship'?`<label class="op-label">Synthetic contact value<input id="op-email" value="${esc(ui.email)}" placeholder="name@example.invalid"></label><div class="op-command-grid">${['update_contact','withdraw_consent','restore_consent','open_holding','classify_restricted','classify_internal','log_contact'].map(c=>`<button data-op-command="${c}" class="${c==='update_contact'?'primary':''}">${commands[c]}</button>`).join('')}</div>`:'<p class="op-hint">This party scope contains no relationship, holding, contact or name. Select a relationship above for business commands.</p>'}<details class="op-controls" ${ui.controlsOpen?'open':''}><summary>Test table defaults and major-key overrides</summary><p class="tiny">Table policy applies to every bound row. Party-key exclusions intersect every scope that includes this party. Denials win.</p><div class="op-command-grid">${['exclude_party_us','restore_party_us','table_contact_local','table_contact_restore'].map(c=>`<button data-op-command="${c}">${commands[c]}</button>`).join('')}</div></details><div class="op-tx"><div class="eyebrow">LAST LOCAL TRANSACTION</div>${tx?`<b>${esc(commands[tx.command]||tx.command)}</b><p>${tx.changed.length} changed resources · ${tx.affected_scope_ids.length} impacted scopes · ${tx.idempotent_replay?'idempotent replay':'committed'}</p><code>${esc(tx.request_id)}</code><div class="op-tags">${tx.affected_scope_ids.map(id=>chip(m.scopes.find(s=>s.id===id)?.name||short(id))).join('')}</div><p class="tiny">Business rows + binding/rule updates + versions + outbox + audit + receipt commit together. Remote acknowledgement is separate.</p>`:'<p>Choose a command to create a transaction receipt.</p>'}</div><button id="op-replay" ${ui.lastRequest?'':'disabled'}>Replay last request ID</button></div></section><section class="panel"><div class="panelhead"><div><h2>Recipient projection</h2><p>${esc(ui.dest)} → ${st.city} (${st.country})</p></div>${chip(st.paused?'INGRESS PAUSED':fresh?'CURRENT DECISION':'AWAITING RECEIPT',fresh&&!st.paused?'':'wait')}</div><div class="pad"><div class="op-receipt"><div><b>${rs.length}</b><span>bound source rows</span></div><div><b>${plan.rows.length}</b><span>currently approved</span></div><div><b>${actual?.rows.length||0}</b><span>stored recipient rows</span></div></div><p class="op-hint">${actual?`Stored v${actual.data_version} / g${actual.policy_generation} / r${actual.decision_revision}. ${fresh?'Ordinary data updates may still be in transit.':'A changed authorisation revision blocks reads until reconciliation.'}`:'No receipt yet. A blocked, never-authorised destination receives no graph.'}</p><div class="actions"><button id="op-read" class="primary">Test business read</button><button data-pause="${st.id}" data-value="${!st.paused}">${st.paused?'Resume':'Pause'} ${st.city}</button><button id="op-preview">${live?'Evaluate with OPA':'Evaluate policy'}</button></div>${ui.read?`<div class="rulebox">${esc(ui.read)}</div>`:''}<div class="op-plan-label">${ui.preview?(live?'OPA evaluation':'Simulation evaluation'):'Browser policy mirror'} · excludes dependency orphans</div><div class="tablewrap"><table><thead><tr><th>Dataset</th><th>Source</th><th>Allow</th><th>Stored</th></tr></thead><tbody>${Object.keys(m.tables).filter(t=>rs.some(r=>r.table===t)).map(t=>`<tr data-op-table="${t}" class="${ui.table===t?'selected':''}" tabindex="0" role="button"><td>${esc(t)}</td><td>${rs.filter(r=>r.table===t).length}</td><td>${plan.row_counts[t]||0}</td><td>${actual?.rows.filter(r=>r.table===t).length||0}</td></tr>`).join('')}</tbody></table></div></div></section></div><section class="panel"><div class="panelhead"><div><h2>Inspect ${esc(ui.table)}</h2><p>Full owner rows on the left. Physically projected fields on the right.</p></div>${chip(ui.table)}</div><div class="op-compare"><div><span class="eyebrow">SOURCE / SINGAPORE</span><pre class="op-json">${esc(JSON.stringify(rs.filter(r=>r.table===ui.table).slice(0,8).map(r=>r.row),null,2))}</pre></div><div><span class="eyebrow">STORED / ${esc(st.city.toUpperCase())}</span><pre class="op-json">${esc(JSON.stringify(actual?.rows.filter(r=>r.table===ui.table).slice(0,8).map(r=>r.row)||[],null,2))}</pre></div></div><div class="op-decisions">${plan.decisions.filter(d=>d.table===ui.table).map(d=>`<div>${chip(d.allow?'ALLOW':'WITHHELD',d.allow?'':'denied')}<code>${short(d.resource_id)}</code><span>${esc(d.reason)}</span></div>`).join('')||'<p>No rows of this table are bound to the selected scope.</p>'}</div></section><div class="op-next"><div><h2>See the movement across the three stores.</h2><p>Party and relationship transfers share the global decision stream. Animations show recent acknowledgements.</p></div><button id="op-map" class="primary">Watch global monitor ↗</button></div><p class="tiny">Synthetic example: consent controls servicing contact sharing by relationship, purpose and channel. It is not a universal lawful-basis rule for banking. Owner data is retained; projection removal does not certify backup deletion.</p>`;}
export function bindOperational(ctx){const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],reset=()=>{ui.preview=null;ui.read=null;};if($('#op-email'))$('#op-email').oninput=e=>ui.email=e.target.value;if($('.op-controls'))$('.op-controls').ontoggle=e=>ui.controlsOpen=e.target.open;if($('#op-scope'))$('#op-scope').onchange=e=>{ui.scope=e.target.value;reset();ctx.render();};if($('#op-dest'))$('#op-dest').onchange=e=>{ui.dest=e.target.value;reset();ctx.render();};$$('[data-op-table]').forEach(el=>{const fn=()=>{ui.table=el.dataset.opTable;ctx.render();};el.onclick=fn;el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();fn();}};});$$('[data-op-command]').forEach(el=>el.onclick=async()=>{const {s}=chosen(ctx.op()),body={command:el.dataset.opCommand,request_id:crypto.randomUUID(),expected_version:s.data_version};if(body.command==='update_contact')body.value=$('#op-email').value;el.disabled=true;try{ui.result=await ctx.command(s.id,body);ui.lastRequest={sid:s.id,body};reset();await ctx.refresh();ctx.toast(`${ui.result.affected_scope_ids.length} scopes queued after one local commit.`);}catch(e){ctx.toast(e.message);}ctx.render();});if($('#op-replay'))$('#op-replay').onclick=async()=>{try{ui.result=await ctx.command(ui.lastRequest.sid,ui.lastRequest.body);ctx.toast('Same receipt returned; no duplicate write or outbox.');}catch(e){ctx.toast(e.message);}ctx.render();};if($('#op-preview'))$('#op-preview').onclick=async()=>{try{ui.preview=await ctx.preview(ui.scope,ui.dest);}catch(e){ctx.toast(e.message);}ctx.render();};if($('#op-read'))$('#op-read').onclick=async()=>{try{const p=await ctx.read(ui.scope,ui.dest);ui.read=`Allowed · ${p.rows.length} rows · business version ${p.data_version}`;}catch(e){ui.read=e.message;}ctx.render();};if($('#op-map'))$('#op-map').onclick=ctx.map;}
